#!/usr/bin/env python3
"""Union of PAIR best_outcome=失败 across v4-pro / Qwen / v4-flash / GLM v3.15 runs."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

DEFAULT_RUNS = {
    "v4-pro": Path("/root/pair_baseline_v315_run/results.jsonl"),
    "qwen3.7-plus": Path("/root/pair_baseline_v315_qwen37plus_run/results.jsonl"),
    "v4-flash": Path("/root/pair_baseline_v315_flash_run/results.jsonl"),
    "glm-5.3-flash": Path("/root/pair_baseline_v315_glm53flash_run/results.jsonl"),
}


def failed_ids(path: Path) -> set[str]:
    out: set[str] = set()
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            row = json.loads(line)
            if row.get("best_outcome") == "失败":
                out.add(row["sample_id"])
    return out


def main() -> None:
    p = argparse.ArgumentParser()
    p.add_argument("--out", type=Path, required=True)
    p.add_argument("--json-summary", type=Path, default=None)
    args = p.parse_args()

    per_run: dict[str, list[str]] = {}
    union: set[str] = set()
    for name, path in DEFAULT_RUNS.items():
        if not path.is_file():
            raise SystemExit(f"missing {name}: {path}")
        ids = failed_ids(path)
        per_run[name] = sorted(ids)
        union |= ids

    ordered = sorted(union)
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text("\n".join(ordered) + ("\n" if ordered else ""), encoding="utf-8")
    print(f"wrote {len(ordered)} sample_id -> {args.out}")

    if args.json_summary:
        payload = {"union_n": len(ordered), "per_run_fail_n": {k: len(v) for k, v in per_run.items()}, "per_run": per_run}
        args.json_summary.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        print(f"summary -> {args.json_summary}")


if __name__ == "__main__":
    main()

